+export type InvitationStatus = "pending" | "claimed" | "completed" | "revoked" | "expired";
+
+export type Invitation = {
+  id: string;
+  token_hash: string;
+  email: string;
+  name: string | null;
+  status: InvitationStatus;
+  expires_at: number;
